-- SYNQORIA P01-B0003 / P04 foundation. This migration is NOT run against PostgreSQL yet.
-- Identities must be generated by a trusted service, not accepted from a patient/API body.
-- This establishes composite tenant/facility referential scope; authorization requires
-- verified server-side identity, grants, consent and patient-level review separately.
CREATE TABLE hospital_cells (
  cell_id uuid PRIMARY KEY,
  cell_status text NOT NULL CHECK (cell_status IN ('ACTIVE','SUSPENDED','RETIRED')),
  revision bigint NOT NULL DEFAULT 1 CHECK (revision > 0)
);

CREATE TABLE hospital_tenants (
  tenant_id uuid PRIMARY KEY,
  cell_id uuid NOT NULL REFERENCES hospital_cells(cell_id),
  tenant_status text NOT NULL CHECK (tenant_status IN ('ACTIVE','SUSPENDED','RETIRED')),
  revision bigint NOT NULL DEFAULT 1 CHECK (revision > 0),
  UNIQUE (tenant_id, cell_id)
);

CREATE TABLE hospital_facilities (
  tenant_id uuid NOT NULL,
  cell_id uuid NOT NULL,
  facility_id uuid NOT NULL,
  facility_code text NOT NULL CHECK (length(btrim(facility_code)) BETWEEN 1 AND 80),
  facility_status text NOT NULL CHECK (facility_status IN ('ACTIVE','SUSPENDED','RETIRED')),
  revision bigint NOT NULL DEFAULT 1 CHECK (revision > 0),
  PRIMARY KEY (tenant_id, facility_id),
  FOREIGN KEY (tenant_id, cell_id) REFERENCES hospital_tenants(tenant_id, cell_id),
  UNIQUE (tenant_id, facility_code)
);

CREATE TABLE hospital_departments (
  tenant_id uuid NOT NULL,
  facility_id uuid NOT NULL,
  department_id uuid NOT NULL,
  department_code text NOT NULL CHECK (length(btrim(department_code)) BETWEEN 1 AND 80),
  department_status text NOT NULL CHECK (department_status IN ('ACTIVE','SUSPENDED','RETIRED')),
  revision bigint NOT NULL DEFAULT 1 CHECK (revision > 0),
  PRIMARY KEY (tenant_id, facility_id, department_id),
  FOREIGN KEY (tenant_id, facility_id) REFERENCES hospital_facilities(tenant_id, facility_id),
  UNIQUE (tenant_id, facility_id, department_code)
);

CREATE TABLE hospital_locations (
  tenant_id uuid NOT NULL,
  facility_id uuid NOT NULL,
  department_id uuid NOT NULL,
  location_id uuid NOT NULL,
  location_code text NOT NULL CHECK (length(btrim(location_code)) BETWEEN 1 AND 80),
  location_status text NOT NULL CHECK (location_status IN ('ACTIVE','SUSPENDED','RETIRED')),
  revision bigint NOT NULL DEFAULT 1 CHECK (revision > 0),
  PRIMARY KEY (tenant_id, facility_id, department_id, location_id),
  FOREIGN KEY (tenant_id, facility_id, department_id)
      REFERENCES hospital_departments(tenant_id, facility_id, department_id),
  UNIQUE (tenant_id, facility_id, department_id, location_code)
);

-- No RLS allow policy is supplied in this foundation. Even otherwise valid SQL
-- clients must not acquire protected table access before a reviewed, testable,
-- non-spoofable server identity binding and read/write policy is installed.
-- Custom PostgreSQL session variables alone are NOT a trust boundary: apps can set them.
ALTER TABLE hospital_cells ENABLE ROW LEVEL SECURITY;
ALTER TABLE hospital_cells FORCE ROW LEVEL SECURITY;
ALTER TABLE hospital_tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE hospital_tenants FORCE ROW LEVEL SECURITY;
ALTER TABLE hospital_facilities ENABLE ROW LEVEL SECURITY;
ALTER TABLE hospital_facilities FORCE ROW LEVEL SECURITY;
ALTER TABLE hospital_departments ENABLE ROW LEVEL SECURITY;
ALTER TABLE hospital_departments FORCE ROW LEVEL SECURITY;
ALTER TABLE hospital_locations ENABLE ROW LEVEL SECURITY;
ALTER TABLE hospital_locations FORCE ROW LEVEL SECURITY;
REVOKE ALL ON hospital_cells, hospital_tenants, hospital_facilities,
  hospital_departments, hospital_locations FROM PUBLIC;
